/* MODULE kn02 · Bước 5 Chọn kênh · Phân phối và độ phủ điểm bán
   8 bài × 7 câu. Thương hiệu nêu như ví dụ công khai; mọi con số là MINH HOẠ và tự khớp nhau. */
BAI_ADD({ mod:'kn02', lessons:[

/* ------------------------------------------------------------------ 01 */
{ id:'B:kn02-01', skill:'measure', read:'7 phút', t:'Có mặt ở 30% cửa hàng là nhiều hay ít?',
  situation:'Bạn phụ trách một loại nước tăng lực mới ở Đồng Nai. Báo cáo của nhà phân phối ghi: hàng đã vào 120 trên tổng 400 điểm bán có bán nước giải khát trong tỉnh, tức 30%. Sếp chê con số thấp và muốn dồn tiền mở thêm điểm. Nhưng 120 điểm đó gồm các cửa hàng tiện lợi, căng tin khu công nghiệp và tạp hoá lớn gần chợ.',
  concept:{ name:'Độ phủ số và độ phủ theo doanh số',
    body:'<b>Độ phủ số</b> (numeric distribution) đếm có bao nhiêu phần trăm điểm bán có hàng của bạn, mỗi điểm tính như nhau. <b>Độ phủ theo doanh số</b> (weighted distribution) tính các điểm có hàng chiếm bao nhiêu phần trăm doanh số của cả ngành hàng. Một cửa hàng bán 500 lon mỗi tháng nặng ký hơn một quầy bán 20 lon. Hai con số đọc cùng nhau mới cho biết bạn đang có mặt ở đâu: độ phủ số thấp mà độ phủ theo doanh số cao nghĩa là bạn đã ở đúng chỗ quan trọng.' },
  example:'400 điểm bán cả ngành hàng bán 100.000 lon mỗi tháng. 120 điểm có hàng của bạn bán tổng 60.000 lon nước tăng lực các loại. Độ phủ số 30%, nhưng độ phủ theo doanh số 60%. Thêm 280 điểm còn lại chỉ mở thêm 40% doanh số ngành, rải trên nhiều điểm nhỏ tốn công giao hàng. Việc đáng làm trước là tăng bán ở 120 điểm mạnh, sau đó mới chọn lọc thêm điểm.',
  takeaway:'Đếm cửa hàng cho biết bạn ở bao nhiêu nơi; đo theo doanh số cho biết bạn ở đúng nơi hay không.',
  apply:'Lấy danh sách điểm bán của một sản phẩm bạn biết. Chia thành điểm lớn và điểm nhỏ, ước lượng doanh số ngành hàng mỗi nhóm, rồi nói trong 60 giây độ phủ theo doanh số khoảng bao nhiêu.',
  mistakes:['Chỉ báo cáo độ phủ số vì dễ đếm, bỏ qua điểm nào bán nhiều.','Đuổi theo số điểm bán bằng cách nhét hàng vào các quầy rất nhỏ.'],
  q:[
  { type:'mcq', stem:'Đoán trước: hàng có mặt ở 30% số điểm bán. Độ phủ theo doanh số của bạn khả năng cao là bao nhiêu?',
    options:[{k:'a',t:'Đúng bằng 30%, vì hai cách đo luôn cho cùng một kết quả'},{k:'b',t:'Luôn thấp hơn 30%, vì hàng mới thường chỉ vào được điểm nhỏ'},
             {k:'c',t:'Có thể cao hơn hoặc thấp hơn, tuỳ bạn đang ở điểm lớn hay nhỏ'},{k:'d',t:'Không tính được nếu không có dữ liệu bán của riêng thương hiệu mình'}],
    answer:'c', why:{a:'Hai con số chỉ bằng nhau khi mọi điểm bán lớn như nhau, điều hiếm khi xảy ra.',
      b:'Hàng mới có thể vào điểm lớn trước, như trường hợp này, nên không có quy luật luôn thấp hơn.',
      c:'Đúng. Độ phủ theo doanh số phụ thuộc vào quy mô của chính những điểm có hàng.',
      d:'Độ phủ theo doanh số dùng doanh số của cả ngành hàng tại điểm bán, không phải doanh số riêng của bạn.'} },
  { type:'mcq', stem:'Độ phủ số 30%, độ phủ theo doanh số 60%. Sếp muốn dồn tiền mở thêm điểm. Bạn đề xuất gì?',
    options:[{k:'a',t:'Mở thêm thật nhanh 280 điểm còn lại cho đủ phủ khắp tỉnh'},{k:'b',t:'Tăng bán tại 120 điểm mạnh trước, rồi chọn lọc thêm điểm lớn'},
             {k:'c',t:'Rút khỏi các điểm nhỏ trong 120 điểm để dồn hàng cho điểm lớn'},{k:'d',t:'Giữ nguyên, vì 60% theo doanh số đã là mức rất tốt rồi, không cần làm gì thêm'}],
    answer:'b', why:{a:'280 điểm còn lại chỉ chiếm 40% doanh số ngành, chi phí giao hàng cao trên mỗi lon.',
      b:'Đúng. Bạn đã ở chỗ quan trọng; khai thác sâu trước, mở rộng có chọn lọc sau.',
      c:'Điểm nhỏ đã có hàng thì giữ không tốn thêm nhiều; rút ra chỉ làm mất doanh số.',
      d:'Có mặt chưa có nghĩa là bán tốt; vẫn còn việc tăng bán tại các điểm đang có hàng.'} },
  { type:'calc', stem:'400 điểm bán cả ngành bán 100.000 lon/tháng. 120 điểm có hàng của bạn bán tổng 60.000 lon (mọi hãng). Độ phủ theo doanh số là bao nhiêu phần trăm?',
    unit:'%', ans:60, tol:0.1, wrong:[[30,'SAI_MAU_SO'],[50,'SAI_TINH_TOAN']], errors:['SAI_MAU_SO'],
    steps:['Độ phủ theo doanh số = doanh số ngành tại các điểm có hàng ÷ doanh số ngành toàn bộ.','60.000 ÷ 100.000 = <b>60%</b>. (30% là độ phủ số: 120 ÷ 400.)'] },
  { type:'mcq', stem:'Hãng X có độ phủ số 70% nhưng độ phủ theo doanh số chỉ 35%. Chẩn đoán nào hợp lý nhất?',
    options:[{k:'a',t:'X có mặt ở nhiều điểm nhỏ, vắng ở các điểm bán lớn'},{k:'b',t:'X đang bán tốt hơn thị trường vì phủ tới 70% cửa hàng'},
             {k:'c',t:'Số liệu sai, vì độ phủ theo doanh số không thể thấp hơn độ phủ số'},{k:'d',t:'X cần giảm giá để kéo độ phủ theo doanh số lên bằng độ phủ số'}],
    answer:'a', why:{a:'Đúng. Có mặt nhiều nơi nhưng những nơi đó chỉ chiếm 35% doanh số ngành.',
      b:'Phủ 70% điểm nhưng vắng mặt ở phần lớn doanh số ngành, đó là điểm yếu.',
      c:'Hoàn toàn có thể thấp hơn khi các điểm có hàng đều nhỏ.',
      d:'Giá không đưa hàng vào điểm lớn; cần làm việc với các điểm đó.'} },
  { type:'mcq', stem:'Vì sao người làm marketing hàng tiêu dùng nhanh thường theo dõi cả hai con số chứ không chỉ một?',
    options:[{k:'a',t:'Vì báo cáo có nhiều chỉ số trông chuyên nghiệp hơn với sếp'},{k:'b',t:'Vì độ phủ số dùng cho nội bộ, còn độ phủ doanh số dùng để báo nhà phân phối'},
             {k:'c',t:'Một số đo rộng, một số đo chất lượng của sự có mặt'},{k:'d',t:'Vì nhà bán lẻ bắt buộc hãng phải báo cáo cả hai chỉ số này hằng tháng'}],
    answer:'c', why:{a:'Mục đích là ra quyết định, không phải trang trí báo cáo.',
      b:'Cả hai đều dùng nội bộ để chọn nơi đầu tư; không có phân công như vậy.',
      c:'Đúng. Độ phủ số cho biết bao nhiêu nơi, độ phủ theo doanh số cho biết những nơi đó quan trọng tới đâu.',
      d:'Không có yêu cầu chung như vậy; hãng theo dõi vì lợi ích của chính mình.'} },
  { type:'mcq', stem:'Tình huống mới: một hãng dầu gội có độ phủ số 50% và theo doanh số 80%. Muốn tăng doanh số nhanh nhất, nên nhìn vào đâu trước?',
    options:[{k:'a',t:'Tìm 50% điểm chưa có hàng và phủ hết chúng trong quý này'},{k:'b',t:'Chạy quảng cáo để kéo khách tới cửa hàng nào cũng được'},
             {k:'c',t:'Giảm số mã hàng để nhà phân phối dễ giao hơn'},{k:'d',t:'Tăng số mã và chỗ trưng bày ở các điểm đang có hàng sẵn rồi'}],
    answer:'d', why:{a:'50% điểm chưa có chỉ chiếm 20% doanh số ngành, phủ hết tốn nhiều mà được ít.',
      b:'Quảng cáo đưa khách tới những nơi không có hàng thì phí tiền.',
      c:'Giảm mã có thể làm mất chỗ trên kệ tại chính các điểm lớn.',
      d:'Đúng. Bạn đã ở nơi chiếm 80% doanh số ngành; đào sâu tại đó hiệu quả hơn.'} },
  { type:'mcq', stem:'Nhà phân phối báo độ phủ số tăng từ 30% lên 45% trong một tháng nhưng doanh số gần như không đổi. Điều gì có khả năng đang xảy ra?',
    options:[{k:'a',t:'Hàng mới vào chủ yếu là các điểm rất nhỏ, bán ít, chỉ kéo số điểm lên'},{k:'b',t:'Khách chưa kịp biết nên cần thêm vài tháng là doanh số tự tăng theo'},
             {k:'c',t:'Độ phủ số tăng nhưng giá bán lẻ đã bị đẩy lên cao'},{k:'d',t:'Đối thủ vừa giảm giá mạnh đúng lúc bạn mở thêm điểm'}],
    answer:'a', why:{a:'Đúng. Thêm nhiều điểm nhỏ làm độ phủ số tăng mạnh mà độ phủ theo doanh số gần như không nhích.',
      b:'Có thể có độ trễ, nhưng giả thuyết đầu tiên cần kiểm là chất lượng điểm mới.',
      c:'Không có dữ kiện nào về giá; đây là suy đoán không căn cứ.',
      d:'Có thể, nhưng thiếu dữ kiện; trong khi quy mô điểm mới là lời giải kiểm tra được ngay.'} }
  ] },

/* ------------------------------------------------------------------ 02 */
{ id:'B:kn02-02', skill:'channel', read:'7 phút', t:'Giá bán lẻ 20.000 đồng, hãng thực thu được bao nhiêu?',
  situation:'Bạn ra mắt một loại bánh gạo, giá bán lẻ đề xuất 20.000 đồng một gói. Hàng đi qua nhà phân phối cấp tỉnh rồi tới tạp hoá. Tạp hoá muốn lãi 15% trên giá bán lẻ, nhà phân phối muốn lãi 8% trên giá bán cho tạp hoá. Phòng tài chính hỏi: giá xuất xưởng cho nhà phân phối là bao nhiêu để mọi người trong chuỗi đều có lãi?',
  concept:{ name:'Chiết khấu kênh tính ngược từ giá bán lẻ',
    body:'Mỗi mắt xích trong kênh, <b>nhà phân phối</b>, <b>đại lý</b>, cửa hàng, đều cần một khoản lãi để chịu giữ hàng, giao hàng và bán hàng cho bạn. Cách tính đúng là đi ngược từ giá khách trả: trừ lãi của cửa hàng, rồi trừ lãi của nhà phân phối, ra giá hãng thu về. Lưu ý mỗi khoản lãi tính trên giá bán của chính mắt xích đó, nên không được cộng dồn phần trăm rồi trừ một lần. Nếu chiết khấu quá mỏng, không ai chịu đẩy hàng của bạn.' },
  example:'Tạp hoá bán 20.000 đồng, lãi 15% nên mua vào 20.000 × 0,85 = 17.000 đồng. Nhà phân phối bán 17.000 đồng, lãi 8% nên mua vào 17.000 × 0,92 = 15.640 đồng. Hãng thực thu 15.640 đồng, tức khoảng 78% giá bán lẻ. Nếu giá vốn là 11.000 đồng, hãng còn 4.640 đồng mỗi gói để trả quảng cáo và lãi.',
  takeaway:'Tính ngược từ giá khách trả, trừ lãi từng mắt xích trên giá bán của nó.',
  apply:'Chọn một món bạn mua ở tạp hoá. Giả định cửa hàng lãi 15%, nhà phân phối lãi 8%, rồi nói trong 60 giây hãng thu về bao nhiêu mỗi món.',
  mistakes:['Cộng 15% + 8% = 23% rồi trừ một lần trên giá bán lẻ.','Ép chiết khấu thật mỏng để giữ lãi cho hãng, rồi không ai chịu đẩy hàng.'],
  q:[
  { type:'mcq', stem:'Đoán trước: giá bán lẻ 20.000 đồng, cửa hàng lãi 15%, nhà phân phối lãi 8%. Hãng thực thu khoảng bao nhiêu?',
    options:[{k:'a',t:'Khoảng 15.400 đồng, vì trừ thẳng 23% trên giá bán lẻ'},{k:'b',t:'Khoảng 15.640 đồng, trừ lần lượt lãi của tạp hoá rồi của nhà phân phối'},
             {k:'c',t:'Khoảng 17.000 đồng, vì nhà phân phối lấy lãi từ phía cửa hàng'},{k:'d',t:'Khoảng 18.400 đồng, vì chỉ trừ lãi của nhà phân phối'}],
    answer:'b', why:{a:'Cộng dồn phần trăm rồi trừ một lần là sai, vì 8% tính trên 17.000 chứ không phải 20.000.',
      b:'Đúng. 20.000 × 0,85 × 0,92 = 15.640 đồng.',
      c:'17.000 là giá cửa hàng mua vào; nhà phân phối còn phải lấy lãi trước khi trả cho hãng.',
      d:'Bỏ sót lãi của cửa hàng, mắt xích lớn nhất trong chuỗi.'} },
  { type:'mcq', stem:'Nhà phân phối đòi tăng lãi từ 8% lên 12% mới chịu đẩy bánh gạo. Bạn chọn cách nào?',
    options:[{k:'a',t:'Đồng ý ngay, tăng giá bán lẻ lên để bù phần chênh cho hãng'},{k:'b',t:'Từ chối, tự thuê xe giao thẳng tới từng tạp hoá trong tỉnh'},
             {k:'c',t:'Tính lại lãi của hãng ở mức 12%, đổi phần tăng lấy cam kết độ phủ'},{k:'d',t:'Giảm lãi của tạp hoá từ 15% xuống 11% để nhà phân phối có thêm'}],
    answer:'c', why:{a:'Tăng giá bán lẻ ảnh hưởng tới người mua; cần tính trước khi quyết.',
      b:'Tự giao cho hàng trăm tạp hoá thường tốn hơn nhiều so với trả thêm cho nhà phân phối.',
      c:'Đúng. Biết mình còn lãi bao nhiêu rồi đổi phần chi thêm lấy cam kết đo được như số điểm bán mới.',
      d:'Tạp hoá mất lãi sẽ đẩy hàng của đối thủ thay vì hàng của bạn.'} },
  { type:'calc', stem:'Giá bán lẻ 20.000 đồng. Tạp hoá lãi 15% trên giá bán lẻ, nhà phân phối lãi 8% trên giá bán cho tạp hoá. Hãng bán cho nhà phân phối giá bao nhiêu đồng?',
    unit:'đồng', ans:15640, tol:1, wrong:[[15400,'SAI_TINH_TOAN'],[17000,'SAI_TINH_TOAN'],[18400,'SAI_MAU_SO']], errors:['SAI_TINH_TOAN'],
    steps:['Tạp hoá mua vào: 20.000 × (1 − 0,15) = 17.000 đồng.','Nhà phân phối mua vào: 17.000 × (1 − 0,08) = <b>15.640 đồng</b>.'] },
  { type:'mcq', stem:'Vì sao không nên ép chiết khấu kênh xuống thật thấp để giữ nhiều lãi cho hãng?',
    options:[{k:'a',t:'Vì pháp luật quy định mức chiết khấu tối thiểu cho mọi mặt hàng'},{k:'b',t:'Vì chiết khấu thấp khiến giá bán lẻ tự động giảm, làm hãng mất lãi'},
             {k:'c',t:'Vì người mua sẽ biết và nghĩ sản phẩm kém chất lượng'},{k:'d',t:'Kênh ưu tiên đẩy hàng nào cho họ lãi hơn'}],
    answer:'d', why:{a:'Không có quy định chung như vậy; đây là chuyện động lực thương mại.',
      b:'Chiết khấu là phần chia trong chuỗi, không tự làm giá bán lẻ giảm.',
      c:'Người mua hiếm khi biết chiết khấu kênh.',
      d:'Đúng. Chỗ trên kệ và lời giới thiệu của chủ tiệm đi theo hàng nào mang lại lãi cho họ.'} },
  { type:'mcq', stem:'Đại lý khác nhà phân phối ở điểm nào quan trọng nhất với hãng?',
    options:[{k:'a',t:'Nhà phân phối mua đứt và giữ kho; đại lý thường bán hộ hãng'},{k:'b',t:'Đại lý luôn ở thành phố lớn, nhà phân phối chỉ ở vùng nông thôn'},
             {k:'c',t:'Đại lý là cửa hàng bán lẻ, nhà phân phối là kho của chính hãng'},{k:'d',t:'Đại lý được phép bán giá tự do, nhà phân phối phải bán giá đề xuất'}],
    answer:'a', why:{a:'Đúng. Ai sở hữu và giữ hàng thì ai chịu rủi ro tồn kho, và điều đó quyết định mức chiết khấu hợp lý.',
      b:'Vị trí không phải điểm phân biệt; cả hai có mặt ở mọi vùng.',
      c:'Nhà phân phối thường là doanh nghiệp độc lập, không phải kho của hãng.',
      d:'Quy định giá tuỳ hợp đồng, không phải đặc điểm cố định của từng loại.'} },
  { type:'mcq', stem:'Tình huống mới: hãng nước mắm đặt giá bán lẻ 50.000 đồng, hãng thu về 39.000 đồng. Tổng phần chia cho kênh chiếm bao nhiêu phần trăm giá bán lẻ?',
    options:[{k:'a',t:'Khoảng 28%, tính bằng 11.000 chia cho 39.000'},{k:'b',t:'Khoảng 39%, vì hãng thu về 39.000 đồng'},
             {k:'c',t:'22%, tính bằng 11.000 chia cho 50.000'},{k:'d',t:'Khoảng 78%, vì đó là phần hãng thu được trên giá bán lẻ'}],
    answer:'c', why:{a:'Chia cho giá hãng thu về là sai mẫu số; câu hỏi hỏi trên giá bán lẻ.',
      b:'Nhầm số tiền với tỉ lệ phần trăm.',
      c:'Đúng. 50.000 − 39.000 = 11.000; 11.000 ÷ 50.000 = 22%.',
      d:'78% là phần hãng giữ lại, không phải phần của kênh.'} },
  { type:'mcq', stem:'Hãng muốn tăng lãi nhưng không đổi giá bán lẻ và không giảm chiết khấu. Cách nào hợp lý?',
    options:[{k:'a',t:'Bớt một cấp trung gian ở vùng hàng bán rất ít'},{k:'b',t:'Giảm giá vốn hoặc tăng số lượng bán qua kênh hiện tại'},
             {k:'c',t:'Tăng giá xuất cho nhà phân phối nhưng giữ nguyên chiết khấu'},{k:'d',t:'Yêu cầu tạp hoá tự trả phí vận chuyển từ kho của nhà phân phối'}],
    answer:'b', why:{a:'Bỏ trung gian ở vùng bán ít thường làm chi phí giao hàng tăng mạnh.',
      b:'Đúng. Khi giá và chia phần đã cố định, lãi thêm đến từ chi phí sản xuất hoặc sản lượng.',
      c:'Tăng giá xuất chính là giảm lãi của nhà phân phối, tức giảm chiết khấu.',
      d:'Đẩy chi phí sang tạp hoá là giảm lãi của họ, họ sẽ đẩy hàng khác.'} }
  ] },

/* ------------------------------------------------------------------ 03 */
{ id:'B:kn02-03', skill:'channel', read:'6 phút', t:'Mở thêm 500 điểm bán hay bán thêm ở 2.000 điểm cũ?',
  situation:'Một hãng cà phê hoà tan đang có mặt ở 2.000 điểm bán tại miền Tây, mỗi điểm bán trung bình 30 hộp mỗi tháng. Ngân sách quý sau chỉ đủ cho một trong hai việc: mở thêm 500 điểm mới ở vùng xa, dự kiến mỗi điểm bán 12 hộp; hoặc làm trưng bày và khuyến mãi tại điểm cũ, dự kiến mỗi điểm bán thêm 4 hộp.',
  concept:{ name:'Rộng hay sâu: độ phủ và tốc độ bán',
    body:'Doanh số từ kênh bằng <b>số điểm có hàng × số bán mỗi điểm</b>. Tăng rộng là mở thêm điểm; tăng sâu là làm mỗi điểm bán nhiều hơn, còn gọi là tăng <b>tốc độ bán</b> (rate of sale). Điểm mới thường bán ít hơn điểm cũ vì ở xa, nhỏ và khách chưa quen. Hãy nhân ra số hộp tăng thêm của từng phương án, rồi đặt cạnh chi phí để chọn. Điểm cũ đã có đường giao hàng nên chi phí thêm cho mỗi hộp thường thấp hơn.' },
  example:'Mở rộng: 500 điểm × 12 hộp = 6.000 hộp thêm mỗi tháng. Đào sâu: 2.000 điểm × 4 hộp = 8.000 hộp thêm. Đào sâu cho thêm 2.000 hộp, lại tận dụng xe giao sẵn có. Nhưng nếu thương hiệu đang thiếu mặt ở vùng xa, nơi khách không mua được, thì cũng cần một kế hoạch mở điểm cho năm sau.',
  takeaway:'Nhân số điểm với số bán mỗi điểm cho từng phương án, rồi mới chọn rộng hay sâu.',
  apply:'Với một sản phẩm quen, ước lượng số điểm bán và số bán mỗi điểm. Nói trong 60 giây: tăng 10% số điểm hay tăng 10% số bán mỗi điểm dễ hơn, và vì sao.',
  mistakes:['Giả định điểm mới bán bằng điểm cũ.','Chỉ so số hộp mà quên chi phí giao hàng tới vùng xa.'],
  q:[
  { type:'mcq', stem:'Đoán trước: 500 điểm mới bán 12 hộp mỗi điểm, hay 2.000 điểm cũ mỗi điểm bán thêm 4 hộp. Phương án nào thêm nhiều hộp hơn?',
    options:[{k:'a',t:'Mở 500 điểm mới, vì 12 hộp mỗi điểm lớn hơn nhiều so với 4 hộp'},{k:'b',t:'Hai phương án bằng nhau vì cùng một mức ngân sách'},
             {k:'c',t:'Chưa so được nếu không biết giá bán mỗi hộp'},{k:'d',t:'Đào sâu điểm cũ, thêm 8.000 hộp so với 6.000 hộp của phương án mở rộng'}],
    answer:'d', why:{a:'So số bán mỗi điểm mà quên nhân với số điểm.',
      b:'Cùng ngân sách không có nghĩa là cùng kết quả.',
      c:'Cùng một sản phẩm cùng giá, so số hộp là đủ.',
      d:'Đúng. 2.000 × 4 = 8.000 so với 500 × 12 = 6.000.'} },
  { type:'mcq', stem:'Kết quả: đào sâu thêm 8.000 hộp, mở rộng thêm 6.000 hộp. Bạn chọn làm gì cho quý sau?',
    options:[{k:'a',t:'Mở rộng, vì có mặt ở nhiều nơi luôn tốt hơn cho thương hiệu về lâu dài'},{k:'b',t:'Chia đôi ngân sách cho mỗi bên một nửa để an toàn'},
             {k:'c',t:'Đào sâu điểm cũ quý này, lên kế hoạch mở điểm vùng xa sau'},{k:'d',t:'Chờ thêm một quý để có dữ liệu rồi mới quyết'}],
    answer:'c', why:{a:'Có mặt rộng quan trọng, nhưng quý này số liệu nghiêng rõ về đào sâu.',
      b:'Chia đôi làm cả hai việc đều thiếu lực, trong khi đã có số để chọn.',
      c:'Đúng. Chọn phương án cho nhiều hộp hơn với chi phí giao thấp hơn, nhưng không bỏ vùng xa.',
      d:'Chờ nghĩa là mất một quý doanh số tăng thêm.'} },
  { type:'calc', stem:'2.000 điểm cũ, mỗi điểm bán thêm 4 hộp/tháng; hoặc 500 điểm mới, mỗi điểm bán 12 hộp/tháng. Phương án đào sâu thêm nhiều hơn mở rộng bao nhiêu hộp mỗi tháng?',
    unit:'hộp', ans:2000, tol:0, wrong:[[8,'NHAM_SO_TUYET_DOI'],[14000,'SAI_TINH_TOAN']], errors:['SAI_TINH_TOAN'],
    steps:['Đào sâu: 2.000 × 4 = 8.000 hộp.','Mở rộng: 500 × 12 = 6.000 hộp.','Chênh: 8.000 − 6.000 = <b>2.000 hộp</b>.'] },
  { type:'mcq', stem:'Vì sao điểm mới ở vùng xa thường bán ít hơn điểm cũ?',
    options:[{k:'a',t:'Vì người dân vùng xa không thích cà phê hoà tan'},{k:'b',t:'Cửa hàng nhỏ hơn, khách chưa quen hãng'},
             {k:'c',t:'Vì nhà phân phối cố tình giao ít hàng tới vùng xa để giữ hàng cho điểm lớn'},{k:'d',t:'Vì hàng tới vùng xa thường bị bán với giá cao hơn đáng kể'}],
    answer:'b', why:{a:'Suy diễn về khẩu vị không có dữ kiện.',
      b:'Đúng. Quy mô điểm nhỏ và thương hiệu chưa quen là lý do phổ biến.',
      c:'Không có dữ kiện về chuyện nhà phân phối giữ hàng.',
      d:'Giá có thể chênh chút ít nhưng không phải lý do chính.'} },
  { type:'mcq', stem:'Tình huống mới: hãng nước giặt đã phủ 90% điểm bán theo doanh số, nhưng mỗi điểm chỉ bán nửa mức đối thủ. Nên tập trung vào đâu?',
    options:[{k:'a',t:'Mở thêm điểm để đạt độ phủ 100% trước khi làm việc khác'},{k:'b',t:'Tăng chiết khấu để nhà phân phối nhận thêm hàng vào kho'},
             {k:'c',t:'Tăng tốc độ bán: trưng bày, giá, lý do để khách chọn'},{k:'d',t:'Giảm số điểm có hàng để tiết kiệm chi phí phục vụ điểm bán'}],
    answer:'c', why:{a:'10% còn lại mang về ít; vấn đề nằm ở tốc độ bán.',
      b:'Nhồi hàng vào kho không làm khách mua nhiều hơn.',
      c:'Đúng. Đã có mặt gần khắp nơi; điểm yếu là mỗi điểm bán chậm.',
      d:'Cắt điểm làm mất doanh số mà không giải quyết chuyện bán chậm.'} },
  { type:'mcq', stem:'Điều gì khiến phương án mở rộng vẫn đáng làm dù cho ít hộp hơn trong ngắn hạn?',
    options:[{k:'a',t:'Có nhiều khách ở vùng đó muốn mua nhưng không mua được'},{k:'b',t:'Mở rộng luôn rẻ hơn đào sâu tính trên mỗi hộp bán thêm'},
             {k:'c',t:'Điểm mới sẽ bán ngay bằng điểm cũ từ tháng đầu'},{k:'d',t:'Nhà phân phối thường thưởng thêm chiết khấu cho mỗi điểm mở mới'}],
    answer:'a', why:{a:'Đúng. Khách không mua được là doanh số bị bỏ ngỏ; có mặt giúp thương hiệu lớn lên dài hạn.',
      b:'Thường ngược lại: vùng xa giao hàng tốn hơn.',
      c:'Điểm mới thường cần thời gian và vẫn nhỏ hơn.',
      d:'Không có dữ kiện như vậy; thưởng thường đi từ hãng sang kênh.'} },
  { type:'mcq', stem:'Công thức nào mô tả đúng doanh số từ kênh phân phối?',
    options:[{k:'a',t:'Số điểm có hàng cộng số bán trung bình mỗi điểm'},{k:'b',t:'Số điểm có hàng nhân số bán mỗi điểm'},
             {k:'c',t:'Độ phủ số nhân với thị phần của hãng trong ngành hàng đó'},{k:'d',t:'Tổng số điểm bán trong vùng chia cho số nhân viên bán hàng'}],
    answer:'b', why:{a:'Cộng hai đại lượng khác đơn vị không cho ra doanh số.',
      b:'Đúng. Đây là lý do có hai đòn bẩy: rộng và sâu.',
      c:'Công thức này trộn hai khái niệm không trực tiếp ra số hộp bán.',
      d:'Đó là khối lượng công việc mỗi nhân viên, không phải doanh số.'} }
  ] },

/* ------------------------------------------------------------------ 04 */
{ id:'B:kn02-04', skill:'measure', read:'7 phút', t:'Kệ trống 3 ngày mỗi tháng thì mất bao nhiêu?',
  situation:'Hãng sữa hạt của bạn có mặt ở 1.000 điểm bán, mỗi điểm bán 50 hộp mỗi tháng. Khảo sát cho thấy trung bình 8% điểm đang hết hàng vào bất kỳ lúc nào. Sếp nói 8% là nhỏ, không đáng lo. Bạn muốn chứng minh bằng số rằng hết hàng đang làm hãng mất tiền thật.',
  concept:{ name:'Tỉ lệ hết hàng và doanh số mất đi',
    body:'<b>Hết hàng</b> (out-of-stock) là lúc khách tới mà kệ không có hàng của bạn. Khi đó khách chia làm hai nhóm: một phần chờ lần sau hoặc đi chỗ khác mua đúng hãng, phần còn lại mua hãng khác và doanh số đó <b>mất hẳn</b>. Doanh số mất = số điểm hết hàng × số bán mỗi điểm × tỉ lệ khách chuyển sang hãng khác. Tệ hơn, khách thử hãng khác có thể không quay lại. Nguyên nhân thường nằm ở khâu đặt hàng và giao hàng, không phải ở quảng cáo.' },
  example:'1.000 điểm × 8% = 80 điểm hết hàng. 80 × 50 hộp = 4.000 hộp khách định mua. Nếu 60% khách lấy hãng khác, bạn mất 2.400 hộp mỗi tháng, gần 5% tổng doanh số 50.000 hộp. Với lãi 8.000 đồng mỗi hộp, đó là 19,2 triệu đồng mỗi tháng, đủ trả một nhân viên theo dõi tồn kho tại các điểm lớn.',
  takeaway:'Hết hàng không chỉ là kệ trống; đó là khách bạn tặng cho đối thủ.',
  apply:'Ghé ba cửa hàng, kiểm xem một hãng quen có hết hàng không. Nói trong 60 giây: nếu hết, bạn sẽ mua gì thay và có quay lại hãng cũ không.',
  mistakes:['Tính mất toàn bộ doanh số ở điểm hết hàng, quên nhóm khách chờ hoặc mua chỗ khác.','Chỉ đo hết hàng ở kho nhà phân phối, không đo trên kệ cửa hàng.'],
  q:[
  { type:'mcq', stem:'Đoán trước: 8% điểm bán hết hàng. Doanh số mất hẳn so với tổng doanh số là bao nhiêu?',
    options:[{k:'a',t:'Đúng 8%, vì 8% điểm bán không có hàng'},{k:'b',t:'Dưới 8%, vì một phần khách chờ hoặc mua chỗ khác'},
             {k:'c',t:'Trên 8%, vì khách hết hàng một lần sẽ bỏ hẳn hãng mãi mãi'},{k:'d',t:'Gần 0%, vì khách trung thành sẽ luôn chờ để mua đúng hãng'}],
    answer:'b', why:{a:'Giả định mọi khách đều chuyển sang hãng khác.',
      b:'Đúng. Chỉ phần khách chuyển hãng mới là doanh số mất hẳn ngay lúc đó.',
      c:'Một phần khách có thể không quay lại, nhưng không phải tất cả và không mãi mãi.',
      d:'Nhiều khách với hàng tiêu dùng nhanh sẵn sàng đổi hãng khi không thấy hàng.'} },
  { type:'mcq', stem:'Bạn có ngân sách cho một việc để giảm hết hàng. Bạn ưu tiên việc gì?',
    options:[{k:'a',t:'Theo dõi tồn kho và lịch giao hàng tại các điểm bán lớn nhất'},{k:'b',t:'Chạy thêm quảng cáo để khách nhớ hãng và chờ mua lần sau'},
             {k:'c',t:'Tăng giá bán lẻ để giảm tốc độ bán cho hàng đỡ hết nhanh'},{k:'d',t:'Tăng tồn kho ở kho nhà phân phối lên gấp đôi'}],
    answer:'a', why:{a:'Đúng. Hết hàng thường do đặt và giao chậm; điểm lớn mất nhiều nhất nên sửa trước.',
      b:'Quảng cáo không đặt được hàng lên kệ trống.',
      c:'Cố tình bán chậm là tự làm mất doanh số.',
      d:'Kho nhà phân phối đầy nhưng kệ vẫn trống nếu không giao đúng lúc.'} },
  { type:'calc', stem:'1.000 điểm bán, 8% hết hàng, mỗi điểm bán 50 hộp/tháng. 60% khách gặp hết hàng mua hãng khác. Hãng mất hẳn bao nhiêu hộp mỗi tháng?',
    unit:'hộp', ans:2400, tol:0, wrong:[[4000,'QUEN_TI_LE_CHUYEN_DOI'],[1600,'NHAM_TI_LE_ROI']], errors:['QUEN_TI_LE_CHUYEN_DOI'],
    steps:['Số điểm hết hàng: 1.000 × 8% = 80 điểm.','Nhu cầu tại các điểm đó: 80 × 50 = 4.000 hộp.','Mất hẳn: 4.000 × 60% = <b>2.400 hộp</b>.'] },
  { type:'mcq', stem:'Vì sao hết hàng có thể gây thiệt hại lớn hơn số hộp mất trong tháng đó?',
    options:[{k:'a',t:'Vì cửa hàng sẽ phạt hãng theo mỗi ngày kệ bị trống'},{k:'b',t:'Vì giá vốn tăng lên khi hàng bị hết'},
             {k:'c',t:'Khách thử hãng khác, thấy ổn thì không quay lại'},{k:'d',t:'Vì nhà phân phối sẽ cắt hợp đồng ngay lần hết hàng đầu tiên'}],
    answer:'c', why:{a:'Có chuỗi có điều khoản phạt, nhưng đó không phải thiệt hại chính.',
      b:'Giá vốn không đổi vì kệ trống.',
      c:'Đúng. Hết hàng đẩy khách đi thử đối thủ; mất một thói quen mua đắt hơn mất một lần bán.',
      d:'Không có dữ kiện nào như vậy; đây là suy diễn.'} },
  { type:'mcq', stem:'Tình huống mới: hãng mì chỉ đo tồn kho ở kho nhà phân phối, thấy luôn đủ hàng. Nhưng khảo sát kệ lại thấy trống nhiều. Chuyện gì đang xảy ra?',
    options:[{k:'a',t:'Khảo sát kệ sai, vì kho còn hàng thì kệ phải có hàng'},{k:'b',t:'Khách mua quá nhanh nên kệ nào cũng luôn trống'},
             {k:'c',t:'Đối thủ lấy hàng của bạn khỏi kệ'},{k:'d',t:'Hàng kẹt ở khâu giao từ kho nhà phân phối tới kệ của cửa hàng'}],
    answer:'d', why:{a:'Kho đủ không bảo đảm kệ đủ; hai chỗ đó cách nhau cả một khâu giao hàng.',
      b:'Nếu vậy kho nhà phân phối cũng sẽ vơi nhanh.',
      c:'Suy đoán không có căn cứ.',
      d:'Đúng. Hàng có ở kho nhưng không tới kệ; cần đo tại điểm bán.'} },
  { type:'mcq', stem:'Muốn biết tỉ lệ khách chuyển hãng khi hết hàng, cách nào đáng tin nhất?',
    options:[{k:'a',t:'Hỏi nhân viên bán hàng của hãng mình'},{k:'b',t:'Lấy luôn con số 60% vì đó là mức phổ biến ở mọi ngành hàng'},
             {k:'c',t:'Hỏi khách tại quầy lúc hết hàng hoặc xem hoá đơn'},{k:'d',t:'Đoán theo mức độ nổi tiếng của thương hiệu trên mạng xã hội'}],
    answer:'c', why:{a:'Nhân viên hãng có thể thiên về phía có lợi cho mình.',
      b:'Con số này khác nhau theo ngành và theo hãng; không nên lấy cố định.',
      c:'Đúng. Quan sát hành vi thật ngay lúc hết hàng cho con số sát nhất.',
      d:'Độ nổi tiếng không cho biết khách sẽ chờ hay đổi hãng.'} },
  { type:'mcq', stem:'Mất 2.400 hộp mỗi tháng, lãi 8.000 đồng mỗi hộp. Số tiền này giúp bạn thuyết phục sếp thế nào?',
    options:[{k:'a',t:'Cho thấy nên tăng giá bán lẻ để bù phần lãi đã mất'},{k:'b',t:'So được 19,2 triệu đồng mất đi với chi phí sửa lỗi'},
             {k:'c',t:'Cho thấy quảng cáo đang kém hiệu quả và cần đổi đơn vị làm quảng cáo'},{k:'d',t:'Cho thấy nên cắt bớt số điểm bán hay bị hết hàng'}],
    answer:'b', why:{a:'Tăng giá không giải quyết chuyện kệ trống.',
      b:'Đúng. Biến kệ trống thành tiền giúp so sánh với chi phí giải quyết.',
      c:'Hết hàng là chuyện cung ứng, không phải chất lượng quảng cáo.',
      d:'Cắt điểm làm mất luôn phần doanh số lúc có hàng.'} }
  ] },

/* ------------------------------------------------------------------ 05 */
{ id:'B:kn02-05', skill:'channel', read:'6 phút', t:'Bán vào trường học, văn phòng hay bệnh viện?',
  situation:'Bạn làm cho một hãng sữa chua uống ít đường ở TP.HCM. Tạp hoá và siêu thị đã phủ khá tốt, doanh số đi ngang. Có ba cửa mới: căng tin trường cấp hai, tủ lạnh tự phục vụ ở văn phòng, và cửa hàng trong khuôn viên bệnh viện. Mỗi nơi có luật chơi riêng, bạn chỉ đủ người làm một nơi.',
  concept:{ name:'Kênh đặc biệt: đúng khoảnh khắc dùng',
    body:'<b>Kênh đặc biệt</b> là những nơi khách mua trong một bối cảnh riêng: trường học, văn phòng, bệnh viện, nhà máy, rạp phim. Người mua ở đây thường bị giới hạn lựa chọn, nên nếu vào được thì cạnh tranh ít hơn. Đổi lại, mỗi nơi có <b>người gác cổng</b> riêng: ban giám hiệu, phòng hành chính, ban quản lý bệnh viện, với điều kiện về hồ sơ, giá và cách bán. Chọn kênh theo câu hỏi: khách mục tiêu dùng sản phẩm vào lúc nào, ở đâu, và ai quyết định cho vào.' },
  example:'Sữa chua ít đường nhắm người đi làm muốn ăn nhẹ buổi chiều. Văn phòng: 40 công ty, mỗi nơi 80 người, 20% mua, mỗi người 8 lần mỗi tháng, tức 5.120 hộp mỗi tháng. Người quyết định là phòng hành chính, chỉ cần lịch châm hàng đều. Căng tin trường có thể đông hơn, nhưng học sinh cấp hai không phải khách mục tiêu và thủ tục chặt hơn nhiều.',
  takeaway:'Chọn kênh đặc biệt theo khoảnh khắc khách mục tiêu dùng hàng, rồi hỏi ai gác cổng.',
  apply:'Nghĩ về một sản phẩm bạn thích. Nói trong 60 giây: nó hợp với kênh đặc biệt nào, ai quyết định cho vào, và họ cần gì.',
  mistakes:['Chọn nơi đông người nhất thay vì nơi có đúng khách mục tiêu.','Quên hỏi người gác cổng cần gì, chỉ lo thuyết phục người dùng.'],
  q:[
  { type:'mcq', stem:'Đoán trước: điều gì hấp dẫn nhất ở kênh đặc biệt như văn phòng hay bệnh viện?',
    options:[{k:'a',t:'Khách ở đó có ít lựa chọn, cạnh tranh thưa hơn'},{k:'b',t:'Giá bán ở đó luôn cao hơn siêu thị nên lãi mỗi hộp lớn hơn'},
             {k:'c',t:'Không cần xin phép ai, cứ mang hàng tới là bán được'},{k:'d',t:'Kênh đặc biệt không phải trả chiết khấu cho bất kỳ bên nào'}],
    answer:'a', why:{a:'Đúng. Trong khuôn viên có giới hạn, sản phẩm vào được thì ít đối thủ hơn.',
      b:'Giá có thể cao hoặc thấp tuỳ nơi, không phải điểm hấp dẫn chính.',
      c:'Ngược lại, hầu hết đều có người gác cổng và điều kiện.',
      d:'Vẫn có chia phần cho căng tin, đơn vị vận hành hoặc người châm hàng.'} },
  { type:'mcq', stem:'Sữa chua ít đường nhắm người đi làm ăn nhẹ buổi chiều. Bạn chọn kênh đặc biệt nào?',
    options:[{k:'a',t:'Căng tin trường cấp hai vì đông học sinh nhất trong ba lựa chọn'},{k:'b',t:'Cửa hàng bệnh viện vì người nhà bệnh nhân mua quà thăm bệnh nhiều'},
             {k:'c',t:'Làm cả ba nơi cùng lúc với số người hiện có'},{k:'d',t:'Tủ lạnh tự phục vụ ở văn phòng'}],
    answer:'d', why:{a:'Đông nhưng không phải khách mục tiêu, thủ tục lại chặt.',
      b:'Có nhu cầu, nhưng không khớp khoảnh khắc ăn nhẹ của người đi làm.',
      c:'Chỉ đủ người cho một nơi; dàn mỏng thì nơi nào cũng làm dở.',
      d:'Đúng. Đúng người, đúng khoảnh khắc buổi chiều, người gác cổng dễ làm việc.'} },
  { type:'calc', stem:'40 văn phòng, mỗi nơi 80 nhân viên. 20% nhân viên mua, mỗi người mua 8 hộp/tháng. Kênh văn phòng bán bao nhiêu hộp mỗi tháng?',
    unit:'hộp', ans:5120, tol:0, wrong:[[25600,'QUEN_TI_LE_CHUYEN_DOI'],[640,'SAI_TINH_TOAN']], errors:['QUEN_TI_LE_CHUYEN_DOI'],
    steps:['Tổng nhân viên: 40 × 80 = 3.200 người.','Người mua: 3.200 × 20% = 640 người.','Số hộp: 640 × 8 = <b>5.120 hộp</b>.'] },
  { type:'mcq', stem:'Ai là người gác cổng quan trọng nhất khi đưa hàng vào căng tin trường học?',
    options:[{k:'a',t:'Học sinh, vì họ là người trực tiếp mua và ăn'},{k:'b',t:'Nhà trường và đơn vị vận hành căng tin'},
             {k:'c',t:'Phụ huynh, vì họ đưa tiền cho con mua quà vặt ở trường mỗi ngày'},{k:'d',t:'Nhà phân phối khu vực, vì họ giao hàng tới trường'}],
    answer:'b', why:{a:'Học sinh là người dùng, nhưng không quyết định hàng nào được bày.',
      b:'Đúng. Họ quyết định cho vào, kèm các yêu cầu về hồ sơ và chất lượng.',
      c:'Phụ huynh có ảnh hưởng gián tiếp, không trực tiếp chọn hàng cho căng tin.',
      d:'Nhà phân phối chỉ giao hàng sau khi đã được nhận.'} },
  { type:'mcq', stem:'Tình huống mới: hãng nước điện giải muốn bán ở khu công nghiệp. Đâu là cách vào hợp lý nhất?',
    options:[{k:'a',t:'Làm việc với bếp ăn và căng tin nhà máy, gắn với ca làm'},{k:'b',t:'Chạy quảng cáo nhắm công nhân rồi chờ họ tự tìm mua ngoài tạp hoá'},
             {k:'c',t:'Đặt hàng ở siêu thị trung tâm thành phố gần khu công nghiệp'},{k:'d',t:'Phát mẫu thử ngoài cổng nhà máy một lần rồi thôi'}],
    answer:'a', why:{a:'Đúng. Có mặt đúng lúc công nhân khát giữa ca, qua đúng người gác cổng.',
      b:'Khách khát giữa ca không có thời gian đi tìm mua.',
      c:'Siêu thị trung tâm không nằm trong khoảnh khắc làm việc của công nhân.',
      d:'Một lần phát mẫu không tạo ra chỗ bán lâu dài.'} },
  { type:'mcq', stem:'Vì sao "chọn nơi đông người nhất" là tiêu chí dễ sai khi chọn kênh đặc biệt?',
    options:[{k:'a',t:'Vì nơi đông người luôn có giá thuê chỗ đắt hơn'},{k:'b',t:'Vì nơi đông người thường đã có hợp đồng độc quyền với hãng khác từ trước'},
             {k:'c',t:'Đông mà không phải khách mục tiêu thì bán ít'},{k:'d',t:'Vì nơi đông người hay bị kiểm tra giấy tờ gắt gao hơn'}],
    answer:'c', why:{a:'Chi phí có thể cao nhưng không phải lý do chính.',
      b:'Có nơi như vậy, nhưng không phải quy luật chung.',
      c:'Đúng. Số người không quan trọng bằng việc họ có cần sản phẩm vào lúc đó không.',
      d:'Thủ tục là rào cản riêng, không phải lý do tiêu chí này sai.'} },
  { type:'mcq', stem:'Vào được văn phòng rồi, điều gì dễ làm mất kênh này nhất?',
    options:[{k:'a',t:'Giá cao hơn tạp hoá dưới toà nhà vài nghìn đồng'},{k:'b',t:'Bao bì chưa đủ đẹp so với hàng nhập khẩu'},
             {k:'c',t:'Ít người biết thương hiệu trên mạng xã hội'},{k:'d',t:'Châm hàng không đều, tủ trống nhiều ngày'}],
    answer:'d', why:{a:'Tiện lợi thường bù được chênh lệch nhỏ về giá.',
      b:'Bao bì ít quan trọng khi sản phẩm gần như độc quyền trong tủ.',
      c:'Khách thấy hàng ngay trong tủ; nhận biết trên mạng không quyết định.',
      d:'Đúng. Phòng hành chính cần sự đều đặn; tủ trống làm họ đổi nhà cung cấp.'} }
  ] },

/* ------------------------------------------------------------------ 06 */
{ id:'B:kn02-06', skill:'channel', read:'7 phút', t:'Vào chuỗi 300 cửa hàng tiện lợi thì phải bán bao nhiêu mới hoà vốn?',
  situation:'Một chuỗi cửa hàng tiện lợi 300 điểm đồng ý nhận bánh quy yến mạch của bạn. Điều kiện: phí mở mã hàng 30 triệu đồng, phí trưng bày 60 triệu đồng mỗi quý, giao hàng về kho tổng đúng hẹn, chấp nhận trả lại hàng cận hạn. Mỗi gói bán ra, hãng lãi gộp 4.000 đồng sau chiết khấu cho chuỗi.',
  concept:{ name:'Chi phí vào chuỗi và mức bán tối thiểu',
    body:'Vào chuỗi bán lẻ hiện đại không chỉ là được nhận hàng. Hãng thường trả <b>phí mở mã</b> (listing fee), phí trưng bày, chịu chiết khấu cao hơn và cam kết giao đúng hạn. Chuỗi cũng theo dõi tốc độ bán, mã nào bán chậm sẽ bị rút sau một thời gian. Vì vậy trước khi ký, hãy tính <b>mức bán hoà vốn</b>: tổng chi phí cố định chia lãi gộp mỗi gói, rồi chia cho số cửa hàng để thấy mỗi cửa hàng phải bán bao nhiêu. Con số nhỏ mới là con số khả thi.' },
  example:'Quý đầu: 30 triệu phí mở mã + 60 triệu phí trưng bày = 90 triệu. Chia 4.000 đồng lãi mỗi gói: cần 22.500 gói. Chia 300 cửa hàng: 75 gói mỗi cửa hàng mỗi quý, tức gần 6 gói mỗi tuần. Nếu hàng tương tự đang bán 10 gói mỗi tuần, mục tiêu khả thi. Nếu chỉ bán 3 gói, bạn đang trả tiền để thua lỗ.',
  takeaway:'Trước khi ký với chuỗi, chia chi phí về mỗi cửa hàng mỗi tuần và so với tốc độ bán thật.',
  apply:'Chọn một chuỗi cửa hàng tiện lợi bạn hay ghé. Giả định phí và lãi như bài, nói trong 60 giây mỗi cửa hàng cần bán bao nhiêu gói mỗi tuần.',
  mistakes:['Chỉ tính phí mở mã, quên phí trưng bày lặp lại mỗi quý.','Tính mức hoà vốn trên doanh thu thay vì trên lãi gộp mỗi gói.'],
  q:[
  { type:'mcq', stem:'Đoán trước: với 90 triệu chi phí quý đầu và 300 cửa hàng, mỗi cửa hàng cần bán khoảng bao nhiêu gói mỗi tuần để hoà vốn?',
    options:[{k:'a',t:'Chưa tới 1 gói mỗi tuần, vì chia cho 300 cửa hàng là nhỏ'},{k:'b',t:'Khoảng 6 gói mỗi tuần, tức 75 gói mỗi cửa hàng mỗi quý'},
             {k:'c',t:'Khoảng 75 gói mỗi tuần, vì cần tới 75 gói mỗi cửa hàng'},{k:'d',t:'Khoảng 25 gói mỗi tuần, vì phải bù cả phí trưng bày của cả năm'}],
    answer:'b', why:{a:'Quên chia chi phí cho lãi mỗi gói trước khi chia cửa hàng.',
      b:'Đúng. 90 triệu ÷ 4.000 ÷ 300 = 75 gói mỗi quý, khoảng 6 gói mỗi tuần.',
      c:'75 là số gói mỗi quý, không phải mỗi tuần.',
      d:'Đang tính chi phí cả năm cho một quý.'} },
  { type:'mcq', stem:'Hàng tương tự trong chuỗi đang bán trung bình 3 gói mỗi cửa hàng mỗi tuần. Bạn làm gì?',
    options:[{k:'a',t:'Ký ngay, vì có mặt trong chuỗi lớn giúp thương hiệu uy tín hơn'},{k:'b',t:'Ký và tăng quảng cáo thật mạnh để kéo tốc độ bán lên gấp đôi'},
             {k:'c',t:'Đàm phán thử ở ít cửa hàng hơn hoặc giảm phí trước khi ký hợp đồng'},{k:'d',t:'Từ bỏ hẳn kênh cửa hàng tiện lợi cho mọi sản phẩm của hãng'}],
    answer:'c', why:{a:'Uy tín không trả được 90 triệu khi mỗi cửa hàng bán thiếu một nửa mức cần.',
      b:'Kỳ vọng gấp đôi tốc độ bán là rủi ro lớn khi chưa có bằng chứng.',
      c:'Đúng. Giảm quy mô hoặc giảm phí để mức hoà vốn gần với tốc độ bán thật.',
      d:'Một phép tính cho một sản phẩm không đủ để bỏ cả kênh.'} },
  { type:'calc', stem:'Phí mở mã 30 triệu đồng, phí trưng bày 60 triệu đồng/quý, lãi gộp 4.000 đồng/gói, 300 cửa hàng. Mỗi cửa hàng cần bán bao nhiêu gói trong quý đầu để hoà vốn?',
    unit:'gói', ans:75, tol:0.5, wrong:[[22500,'SAI_MAU_SO'],[50,'QUEN_CHI_PHI_CO_DINH']], errors:['QUEN_CHI_PHI_CO_DINH'],
    steps:['Chi phí cố định quý đầu: 30 + 60 = 90 triệu đồng.','Số gói hoà vốn: 90.000.000 ÷ 4.000 = 22.500 gói.','Mỗi cửa hàng: 22.500 ÷ 300 = <b>75 gói</b>.'] },
  { type:'mcq', stem:'Vì sao chuỗi cửa hàng tiện lợi hay rút những mã hàng bán chậm?',
    options:[{k:'a',t:'Vì chuỗi muốn ép hãng trả thêm phí mở mã mỗi lần vào lại'},{k:'b',t:'Kệ nhỏ, mỗi chỗ phải mang về đủ doanh thu'},
             {k:'c',t:'Vì hàng bán chậm thường là hàng kém chất lượng'},{k:'d',t:'Vì người mua ở cửa hàng tiện lợi không thích hàng mới'}],
    answer:'b', why:{a:'Có thể có phí khi vào lại, nhưng lý do gốc là hiệu quả chỗ trưng bày.',
      b:'Đúng. Cửa hàng tiện lợi có ít chỗ; mã chậm chiếm chỗ của mã bán nhanh hơn.',
      c:'Bán chậm có nhiều lý do, không nhất thiết do chất lượng.',
      d:'Cửa hàng tiện lợi vẫn thường đưa hàng mới vào thử.'} },
  { type:'mcq', stem:'Điều kiện "chấp nhận trả lại hàng cận hạn" ảnh hưởng thế nào tới phép tính của bạn?',
    options:[{k:'a',t:'Làm giảm lãi thực, cần trừ vào khi tính hoà vốn'},{k:'b',t:'Không đáng kể vì hàng trả lại vẫn bán được ở chỗ khác với giá gần như cũ'},
             {k:'c',t:'Giúp hãng lãi hơn vì chuỗi phải trả phí xử lý hàng trả lại'},{k:'d',t:'Chỉ ảnh hưởng tới nhà phân phối, hãng không bị gì'}],
    answer:'a', why:{a:'Đúng. Hàng trả lại là chi phí thật; bán chậm thì cận hạn nhiều, lãi thực còn thấp hơn.',
      b:'Hàng cận hạn thường phải giảm giá sâu hoặc huỷ.',
      c:'Thường hãng mới là bên chịu phần hàng trả lại.',
      d:'Hãng là bên nhận lại hàng và chịu thiệt.'} },
  { type:'mcq', stem:'Tình huống mới: sang năm thứ hai, chuỗi bỏ phí mở mã, chỉ còn 60 triệu phí trưng bày mỗi quý. Mức hoà vốn mỗi cửa hàng thay đổi thế nào?',
    options:[{k:'a',t:'Không đổi, vì phí trưng bày vẫn giữ nguyên như năm đầu'},{k:'b',t:'Tăng lên, vì chuỗi sẽ đòi thêm chiết khấu bù cho phần phí đã bỏ'},
             {k:'c',t:'Giảm còn 50 gói mỗi cửa hàng mỗi quý'},{k:'d',t:'Giảm còn khoảng 25 gói mỗi cửa hàng mỗi quý'}],
    answer:'c', why:{a:'Phí mở mã đã mất đi nên tổng chi phí giảm.',
      b:'Đề bài không nói gì về chiết khấu mới.',
      c:'Đúng. 60 triệu ÷ 4.000 ÷ 300 = 50 gói.',
      d:'25 gói là phần do phí mở mã đóng góp, không phải mức mới.'} },
  { type:'mcq', stem:'Ngoài phí, điều kiện nào của chuỗi hay làm hãng nhỏ gặp khó nhất?',
    options:[{k:'a',t:'Phải in mã vạch trên bao bì'},{k:'b',t:'Phải có website giới thiệu sản phẩm đầy đủ thông tin'},
             {k:'c',t:'Phải có sẵn quảng cáo truyền hình trên kênh quốc gia'},{k:'d',t:'Giao đúng hẹn, đủ lượng về kho tổng liên tục'}],
    answer:'d', why:{a:'Mã vạch là thủ tục dễ làm, không phải rào cản lớn.',
      b:'Website không phải điều kiện trọng yếu của chuỗi.',
      c:'Chuỗi không đòi quảng cáo truyền hình như điều kiện nhận hàng.',
      d:'Đúng. Năng lực sản xuất và giao hàng đều đặn là chỗ hãng nhỏ hay vấp.'} }
  ] },

/* ------------------------------------------------------------------ 07 */
{ id:'B:kn02-07', skill:'channel', read:'7 phút', t:'Đại lý giận vì hãng bán online rẻ hơn, xử lý sao?',
  situation:'Hãng nồi chiên không dầu của bạn bán qua 150 đại lý điện gia dụng, giá bán lẻ đề xuất 99.000 đồng cho bộ phụ kiện đi kèm. Đại lý mua vào 85.000 đồng. Gian hàng chính hãng trên sàn thương mại điện tử lại chạy khuyến mãi bán 89.000 đồng. Khách tới đại lý xem hàng rồi về đặt online. Hội đại lý doạ ngừng nhập.',
  concept:{ name:'Xung đột kênh',
    body:'<b>Xung đột kênh</b> xảy ra khi hai kênh của cùng một hãng giành cùng một khách, thường vì chênh giá. Kênh bị thiệt sẽ bớt nhiệt tình: bày hàng ít đi, giới thiệu hãng khác. Cách xử lý thường gặp: giữ <b>giá bán thống nhất</b> giữa các kênh, chia vai trò (online bán mã riêng, đại lý bán mã có dịch vụ lắp đặt), hoặc chia phần cho đại lý với đơn online trong khu vực của họ. Mục tiêu không phải loại một kênh, mà để mỗi kênh có lý do tồn tại.' },
  example:'Đại lý mua 85.000 đồng, bán 99.000 đồng thì lãi 14.000 đồng, khoảng 14% giá bán. Muốn giữ khách trước giá online 89.000 đồng, họ phải hạ xuống 89.000 và lãi chỉ còn 4.000 đồng, khoảng 4,5%, không đủ trả mặt bằng. Hãng quyết định: sàn bán đúng giá đề xuất, khuyến mãi dùng quà tặng thay vì giảm giá, và đại lý có mã phụ kiện riêng.',
  takeaway:'Chênh giá giữa các kênh của chính mình sẽ khiến kênh chịu thiệt ngừng bán hàng cho bạn.',
  apply:'Tìm một sản phẩm bán cả ở cửa hàng và trên sàn. So giá hai nơi, rồi nói trong 60 giây: nếu là chủ cửa hàng, bạn sẽ phản ứng thế nào.',
  mistakes:['Coi đại lý giận là chuyện nhỏ vì online đang tăng trưởng.','Giải quyết bằng cách cắt hẳn một kênh thay vì chia lại vai trò.'],
  q:[
  { type:'mcq', stem:'Đoán trước: đại lý phải hạ giá từ 99.000 xuống 89.000 đồng để giữ khách. Lãi của họ còn khoảng bao nhiêu phần trăm giá bán?',
    options:[{k:'a',t:'Khoảng 4,5%, vì chỉ còn 4.000 đồng lãi trên giá bán 89.000 đồng'},{k:'b',t:'Khoảng 10%, vì chỉ giảm đúng 10.000 đồng trên giá bán'},
             {k:'c',t:'Vẫn khoảng 14%, vì giá mua vào cũng giảm theo'},{k:'d',t:'Khoảng 11%, vì 10.000 chia cho 89.000'}],
    answer:'a', why:{a:'Đúng. (89.000 − 85.000) ÷ 89.000 ≈ 4,5%.',
      b:'Nhầm số tiền giảm với tỉ lệ lãi còn lại.',
      c:'Giá mua vào của đại lý vẫn là 85.000 đồng.',
      d:'Đó là tỉ lệ giảm giá, không phải tỉ lệ lãi còn lại.'} },
  { type:'mcq', stem:'Hội đại lý doạ ngừng nhập. Bạn chọn xử lý thế nào?',
    options:[{k:'a',t:'Bỏ hẳn kênh đại lý vì online đang tăng trưởng nhanh hơn'},{k:'b',t:'Đóng gian hàng trên sàn để đại lý hài lòng'},
             {k:'c',t:'Giữ giá thống nhất, khuyến mãi bằng quà, cho đại lý mã riêng'},{k:'d',t:'Tăng chiết khấu cho đại lý đúng bằng mức chênh giá online'}],
    answer:'c', why:{a:'Mất 150 đại lý là mất nơi khách xem, sờ hàng trước khi mua.',
      b:'Bỏ online là bỏ một nhóm khách chỉ mua trên sàn.',
      c:'Đúng. Hết chênh giá, và mỗi kênh có vai trò riêng.',
      d:'Chỉ trả tiền cho xung đột, giá online vẫn kéo khách khỏi đại lý.'} },
  { type:'calc', stem:'Đại lý mua 85.000 đồng. Nếu bán 89.000 đồng, lãi bằng bao nhiêu phần trăm giá bán? (làm tròn 1 chữ số thập phân)',
    unit:'%', ans:4.5, tol:0.1, wrong:[[4.7,'SAI_MAU_SO'],[14.1,'SAI_TINH_TOAN']], errors:['SAI_MAU_SO'],
    steps:['Lãi mỗi bộ: 89.000 − 85.000 = 4.000 đồng.','Tỉ lệ trên giá bán: 4.000 ÷ 89.000 ≈ <b>4,5%</b>. (4,7% là chia nhầm cho giá mua 85.000.)'] },
  { type:'mcq', stem:'Vì sao khách "xem ở đại lý, mua trên mạng" lại là vấn đề cho chính hãng?',
    options:[{k:'a',t:'Vì bán online lãi thấp hơn nên hãng lỗ trên mọi đơn'},{k:'b',t:'Vì sàn thương mại điện tử sẽ tăng phí khi đơn tăng'},
             {k:'c',t:'Vì khách mua online hay trả lại hàng nhiều hơn khách mua ở đại lý'},{k:'d',t:'Đại lý làm phần tư vấn tốn công mà không được trả, nên dần dần sẽ bỏ hãng'}],
    answer:'d', why:{a:'Chưa chắc hãng lỗ; vấn đề là động lực của đại lý.',
      b:'Phí sàn không phải trọng tâm của xung đột này.',
      c:'Không có dữ kiện về tỉ lệ trả hàng.',
      d:'Đúng. Đại lý bỏ công tư vấn mà mất đơn thì sớm muộn sẽ ngừng giới thiệu hãng.'} },
  { type:'mcq', stem:'Tình huống mới: hãng sữa bán cho siêu thị và cho nhà phân phối tạp hoá, nhưng nhà phân phối bán phá giá sang vùng của nhà phân phối khác. Đây là gì?',
    options:[{k:'a',t:'Cạnh tranh lành mạnh giữa các nhà phân phối giúp giá tốt cho khách'},{k:'b',t:'Xung đột kênh do lấn vùng'},
             {k:'c',t:'Chuyện nội bộ của nhà phân phối, không liên quan tới hãng'},{k:'d',t:'Dấu hiệu nhu cầu tăng ở vùng bị lấn nên cần thêm nhà phân phối'}],
    answer:'b', why:{a:'Phá giá sang vùng khác làm nhà phân phối vùng đó mất lãi và bỏ đầu tư.',
      b:'Đúng. Hai mắt xích của cùng hãng giành cùng khách; hãng cần quy định vùng và giá.',
      c:'Hệ thống kênh của hãng yếu đi thì hãng chịu thiệt.',
      d:'Hàng tràn sang do chênh giá, không phải do nhu cầu tăng.'} },
  { type:'mcq', stem:'Cách "chia vai trò" giữa kênh online và đại lý nghĩa là gì?',
    options:[{k:'a',t:'Mỗi kênh bán hàng hoặc dịch vụ khác, khỏi so giá trực tiếp'},{k:'b',t:'Chia đôi thị trường theo tỉnh, mỗi kênh một nửa số tỉnh'},
             {k:'c',t:'Cho mỗi kênh một ngày trong tuần được chạy khuyến mãi riêng'},{k:'d',t:'Online bán giá thấp, đại lý bán giá cao cho khách không rành mạng'}],
    answer:'a', why:{a:'Đúng. Mã riêng hoặc dịch vụ riêng giúp mỗi kênh có lý do để khách chọn.',
      b:'Chia theo tỉnh không thực tế với online, nơi khách ở đâu cũng mua được.',
      c:'Khuyến mãi xoay vòng vẫn tạo chênh giá và giữ nguyên xung đột.',
      d:'Chính chênh giá như vậy là gốc của xung đột.'} },
  { type:'mcq', stem:'Dấu hiệu sớm nào cho thấy xung đột kênh đang làm hại hãng?',
    options:[{k:'a',t:'Doanh số online tăng mạnh trong tháng khuyến mãi'},{k:'b',t:'Có thêm nhiều bình luận hỏi giá trên gian hàng online'},
             {k:'c',t:'Đại lý bày hàng ít đi, nhập đơn nhỏ hơn'},{k:'d',t:'Số lượt tìm kiếm tên thương hiệu trên sàn tăng lên rõ rệt'}],
    answer:'c', why:{a:'Online tăng có thể chỉ là chuyển từ đại lý sang, không phải tín hiệu hại.',
      b:'Bình luận hỏi giá là chuyện bình thường.',
      c:'Đúng. Kênh bị thiệt thu hẹp đầu tư trước khi lên tiếng.',
      d:'Tìm kiếm tăng thường là tín hiệu tốt về nhu cầu.'} }
  ] },

/* ------------------------------------------------------------------ 08 */
{ id:'B:kn02-08', skill:'measure', read:'7 phút', t:'Kênh nào thật sự mang lại lãi?',
  situation:'Hãng dầu ăn của bạn bán qua hai kênh. Siêu thị và chuỗi: hãng thu về 400 triệu đồng mỗi tháng. Tạp hoá qua nhà phân phối: hãng thu về 300 triệu. Sếp muốn dồn thêm người cho siêu thị vì doanh thu lớn hơn. Bạn có số liệu giá vốn và chi phí riêng từng kênh: phí trưng bày, nhân viên đứng quầy, khuyến mãi, hỗ trợ nhà phân phối.',
  concept:{ name:'Lãi đóng góp theo kênh',
    body:'Doanh thu lớn chưa chắc lãi lớn. Mỗi kênh có chi phí riêng: siêu thị đòi phí trưng bày, nhân viên, khuyến mãi; tạp hoá cần hỗ trợ nhà phân phối và đội đi thị trường. <b>Lãi đóng góp của kênh</b> = doanh thu hãng thu về − giá vốn − chi phí riêng của kênh đó. Chia cho doanh thu ra <b>tỉ lệ lãi đóng góp</b> để so sánh các kênh. Đo xong mới quyết định dồn người, dồn tiền về đâu, và kênh nào cần sửa điều khoản.' },
  example:'Siêu thị: 400 triệu − giá vốn 240 triệu − chi phí kênh 100 triệu = 60 triệu, tức 15%. Tạp hoá: 300 triệu − 180 triệu − 30 triệu = 90 triệu, tức 30%. Kênh doanh thu nhỏ hơn lại mang về lãi nhiều hơn. Quyết định hợp lý: đàm phán lại chi phí siêu thị, và tăng người cho tạp hoá.',
  takeaway:'So kênh bằng lãi đóng góp sau chi phí riêng, không phải bằng doanh thu.',
  apply:'Nghĩ về một cửa hàng bán cả tại chỗ và giao đi. Liệt kê chi phí riêng từng cách bán, rồi nói trong 60 giây cách nào lãi hơn.',
  mistakes:['Xếp hạng kênh theo doanh thu.','Chia đều chi phí chung cho các kênh rồi kết luận kênh nhỏ lỗ.'],
  q:[
  { type:'mcq', stem:'Đoán trước: siêu thị thu về 400 triệu, tạp hoá 300 triệu. Kênh nào lãi nhiều hơn?',
    options:[{k:'a',t:'Siêu thị, vì doanh thu lớn hơn 100 triệu'},{k:'b',t:'Bằng nhau, vì cùng một sản phẩm cùng giá vốn trên mỗi chai'},
             {k:'c',t:'Tạp hoá, vì chi phí riêng của tạp hoá bằng không'},{k:'d',t:'Chưa biết, cần trừ giá vốn và chi phí riêng'}],
    answer:'d', why:{a:'Doanh thu chưa trừ chi phí riêng của kênh.',
      b:'Cùng giá vốn mỗi chai, nhưng chi phí kênh khác nhau.',
      c:'Tạp hoá vẫn có chi phí: hỗ trợ nhà phân phối, đội đi thị trường.',
      d:'Đúng. Không có chi phí thì chưa so được lãi.'} },
  { type:'mcq', stem:'Siêu thị lãi đóng góp 15%, tạp hoá 30%. Sếp muốn dồn thêm người cho siêu thị. Bạn đề xuất gì?',
    options:[{k:'a',t:'Làm theo sếp vì siêu thị là kênh của tương lai'},{k:'b',t:'Rút khỏi siêu thị ngay, dồn hết cho tạp hoá'},
             {k:'c',t:'Tăng người cho tạp hoá, đồng thời đàm phán lại chi phí ở siêu thị'},{k:'d',t:'Tăng giá bán trong siêu thị để kéo tỉ lệ lãi lên bằng tạp hoá'}],
    answer:'c', why:{a:'Dồn người cho kênh lãi thấp mà không sửa chi phí là thêm tiền vào chỗ kém.',
      b:'Siêu thị vẫn lãi 60 triệu mỗi tháng; rút ra là mất khoản đó.',
      c:'Đúng. Đầu tư vào kênh lãi cao, sửa điều khoản ở kênh lãi thấp.',
      d:'Tăng giá có thể làm giảm số bán; nên sửa chi phí trước.'} },
  { type:'calc', stem:'Tạp hoá: hãng thu về 300 triệu, giá vốn 180 triệu, chi phí riêng của kênh 30 triệu. Tỉ lệ lãi đóng góp của kênh tạp hoá là bao nhiêu phần trăm?',
    unit:'%', ans:30, tol:0.1, wrong:[[40,'QUEN_CHI_PHI_BIEN_DOI'],[50,'SAI_MAU_SO']], errors:['QUEN_CHI_PHI_BIEN_DOI'],
    steps:['Lãi đóng góp: 300 − 180 − 30 = 90 triệu đồng.','Tỉ lệ: 90 ÷ 300 = <b>30%</b>.'] },
  { type:'mcq', stem:'Vì sao không nên chia đều chi phí chung (văn phòng, giám đốc) cho các kênh khi so sánh?',
    options:[{k:'a',t:'Vì chi phí chung quá nhỏ, không đáng đưa vào tính toán'},{k:'b',t:'Vì kế toán không cho phép chia chi phí chung theo kênh'},
             {k:'c',t:'Chúng vẫn tồn tại dù bỏ kênh nào'},{k:'d',t:'Vì chia đều khiến mọi kênh trông lãi ngang nhau'}],
    answer:'c', why:{a:'Chi phí chung có thể lớn; vấn đề là nó không đổi theo kênh.',
      b:'Không có cấm đoán như vậy; đây là chuyện cách đọc số.',
      c:'Đúng. Bỏ một kênh không làm mất văn phòng; chia đều dễ khiến kênh nhỏ trông như đang lỗ.',
      d:'Chia đều không làm các kênh lãi bằng nhau.'} },
  { type:'mcq', stem:'Tình huống mới: kênh online thu 100 triệu, giá vốn 60 triệu, phí sàn và vận chuyển 35 triệu. Nhận định nào đúng?',
    options:[{k:'a',t:'Online lãi 40%, vì doanh thu trừ giá vốn là 40 triệu'},{k:'b',t:'Online đang lỗ 35 triệu vì phí sàn quá cao'},
             {k:'c',t:'Online lãi đóng góp 5%, mỏng nhất trong ba kênh'},{k:'d',t:'Online lãi đóng góp 35% nhờ không mất chiết khấu cho trung gian'}],
    answer:'c', why:{a:'Quên trừ chi phí riêng của kênh online.',
      b:'100 − 60 − 35 = 5 triệu, vẫn lãi chứ không lỗ.',
      c:'Đúng. 5 ÷ 100 = 5%, thấp hơn siêu thị 15% và tạp hoá 30%.',
      d:'Phí sàn và vận chuyển chính là chi phí thay cho chiết khấu trung gian.'} },
  { type:'mcq', stem:'Ngoài lãi đóng góp, chỉ số nào nên xem thêm khi đánh giá một kênh?',
    options:[{k:'a',t:'Số lượt thích trên trang mạng xã hội của nhà bán lẻ'},{k:'b',t:'Số năm hợp tác với đối tác trong kênh'},
             {k:'c',t:'Tốc độ tăng trưởng và vòng quay vốn của kênh'},{k:'d',t:'Số lượng nhân viên của hãng đang làm việc trong kênh đó'}],
    answer:'c', why:{a:'Lượt thích không đo được hiệu quả phân phối.',
      b:'Thâm niên hợp tác không nói lên kênh đó lãi hay không.',
      c:'Đúng. Kênh lãi mỏng nhưng tăng nhanh, hoặc thu tiền nhanh, có thể vẫn đáng đầu tư.',
      d:'Số nhân viên là chi phí đầu vào, không phải kết quả.'} },
  { type:'mcq', stem:'Siêu thị lãi 15% nhưng mang lại độ nhận biết lớn cho thương hiệu. Cách nhìn nào hợp lý?',
    options:[{k:'a',t:'Giữ kênh, sửa chi phí, nhưng tính rõ lợi ích nhận biết'},{k:'b',t:'Bỏ ngay vì lãi thấp hơn tạp hoá tới một nửa'},
             {k:'c',t:'Lợi ích nhận biết đủ lớn để không cần đo lãi của kênh này'},{k:'d',t:'Chuyển chi phí siêu thị sang ngân sách quảng cáo để kênh trông lãi hơn'}],
    answer:'a', why:{a:'Đúng. Có lợi ích khó đo vẫn cần đo phần đo được và sửa chỗ tốn kém.',
      b:'Lãi thấp hơn vẫn là lãi; bỏ kênh có thể mất cả lợi ích khác.',
      c:'Không đo thì không biết đang trả bao nhiêu cho lợi ích đó.',
      d:'Chuyển mục chi phí chỉ đổi tên, không làm kênh hiệu quả hơn.'} }
  ] }

] });
